<template>
  <v-dialog
    v-model="opened"
    @click:outside.prevent="config.onClickCancel"
    eager
  >
    <v-responsive :aspect-ratio="16 / 8">
      <iframe
        width="100%"
        height="100%"
        :src="url"
        frameborder="0"
        allowfullscreen
        class="iframe-video"
      ></iframe>
    </v-responsive>
  </v-dialog>
</template>

<script>
export default {
  name: 'VideoPlayerDialog',
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  computed: {
    opened() {
      return 'opened' in this.config ? this.config.opened : true
    },
    url() {
      return `${this.config.videoUrl}?autoplay=${this.config?.autoplay ||
        0}&rel=0`
    },
  },
}
</script>

<style lang="scss" scoped>
.iframe-video {
  object-fit: cover;
  overflow: hidden;
}
</style>
