<template>
  <v-stepper non-linear v-model="currentStep" class="stepper">
    <v-stepper-header class="stepper__header" id="loyalty-stepper-header">
      <template v-for="step in steps">
        <v-stepper-step
          :key="step.id"
          :step="step.step"
          :editable="step.editable"
          :complete="step.complete"
        >
          <FormattedText intl :value="step.name" />
        </v-stepper-step>
      </template>
    </v-stepper-header>
    <v-stepper-items>
      <v-stepper-content v-for="step in steps" :key="step.id" :step="step.step">
        <component
          :is="step.component"
          :step="currentStep"
          :formPayload="loyaltyFormInputs"
          :selectedCustomers="customersAdded"
          v-on:loyalty-form-values="onLoyaltyForm"
          v-on:loyalty-accept-message-invitation="onAcceptMessageInvitacion"
          @updateSelectedCustomers="updateSelectedCustomers"
          :style="{
            height: `calc(100vh - ${getCommonStyles}px)`,
          }"
        />
        <div class="fixed-bottom" id="loyalty-stepper-control">
          <div class="d-flex justify-end my-4">
            <CustomButton
              className="mx-2"
              color="accent"
              text="shared.previous"
              intl
              textType="text-button"
              x-large
              @click="previousStep"
              :disabled="isPreviousButtonDisabled"
            />
            <CustomButton
              className="mx-2"
              :text="continueButtonText"
              intl
              textType="text-button"
              x-large
              @click="nextStep"
              :disabled="isContinueButtonDisabled"
            />
          </div>
        </div>
      </v-stepper-content>
    </v-stepper-items>
  </v-stepper>
</template>

<script>
import { isEmpty } from 'ramda'
import { mapActions, mapState } from 'vuex'

import LOYALTY_PROGRAM_EVENTS from '@/config/events/loyaltyProgram'
import { defaultPrizeDescription } from '@/config/loyaltyProgram'

import { getAppLayoutHeaderAndFooterHeight } from '@/tools/view'
import { formatNumberToDb } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import CustomButton from '@/components/shared/CustomButton'

import { steps } from '@/components/LoyaltyViews/LoyaltyProgramConfigView/LoyaltyConfigStepper/stepperConfig'

export default {
  name: 'LoyaltyConfigStepper',
  components: {
    FormattedText,
    CustomButton,
  },
  data() {
    return {
      steps: steps,
      layoutCommonElementsHeight: 0,
      currentStep: 1,
      loyaltyFormInputs: {
        storeName: '',
        rewardAmount: 0,
        prizeDescription: '',
      },
      formIsValid: false,
      customersAdded: [],
    }
  },
  computed: {
    ...mapState('account', {
      storeName: state => state.data.storeName,
    }),
    ...mapState('loyaltyProgramView', ['messageInformationDialog']),
    getCommonStyles() {
      return this.layoutCommonElementsHeight
    },
    isPreviousButtonDisabled() {
      return this.currentStep === 1
    },
    isContinueButtonDisabled() {
      if (this.currentStep === 1 && !this.formIsValid) return true
      if (this.currentStep === 2 && this.customersAdded.length === 0)
        return true
      return false
    },
    continueButtonText() {
      return this.currentStep === this.steps.length
        ? 'shared.finish'
        : 'shared.continue'
    },
  },
  methods: {
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setMessageInformationDialogStatus,
    ]),
    onLoyaltyForm(evt) {
      this.formIsValid = evt.isValid
      this.loyaltyFormInputs = evt.inputs
    },
    getStep(stepNumber) {
      return this.steps.find(step => step.step === stepNumber)
    },
    nextStep() {
      if (this.currentStep === this.steps.length && this.formIsValid) {
        this.persistLoyaltyConfig()
        return
      }
      const stepId = this.getStep(this.currentStep).id
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgramConfig',
        screen: `${stepId.charAt(0).toUpperCase()}${stepId.slice(1)}Step`,
        name: 'Go to next step',
      })
      if (this.currentStep === 1) this.customersAdded = []
      if (this.currentStep === 2) {
        this.openMessageInvitationDialog()
        return
      }
      this.markStepAsComplete(this.currentStep)
      this.currentStep++
    },
    previousStep() {
      if (this.currentStep === 1) return
      const stepId = this.getStep(this.currentStep).id
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgramConfig',
        screen: `${stepId.charAt(0).toUpperCase()}${stepId.slice(1)}Step`,
        name: 'Go to previous step',
      })
      if (this.currentStep === 3) this.customersAdded = []
      this.currentStep -= 1
    },
    markStepAsComplete(stepNumber) {
      const step = this.getStep(stepNumber)
      if (step) step.complete = true
    },
    getLayoutHeight() {
      const layoutComponentsHeight = getAppLayoutHeaderAndFooterHeight(
        'loyalty-view-config'
      )
      const stepperHeaderHeight = document.getElementById(
        'loyalty-stepper-header'
      ).offsetHeight
      this.layoutCommonElementsHeight =
        layoutComponentsHeight + stepperHeaderHeight + 110
    },
    updateSelectedCustomers(customers) {
      this.customersAdded = customers
    },
    openMessageInvitationDialog() {
      const stepId = this.getStep(this.currentStep).id
      this.$track({
        type: 'system',
        action: 'next_step',
        category: 'LoyaltyProgramConfig',
        screen: `${stepId.charAt(0).toUpperCase()}${stepId.slice(1)}Step`,
        name: 'Show whatsapp message',
      })
      this[loyaltyProgramViewActions.setMessageInformationDialogStatus]({
        isOpen: true,
        data: {
          loyaltyFormInputs: {
            ...this.loyaltyFormInputs,
            rewardAmount: formatNumberToDb(this.loyaltyFormInputs.rewardAmount),
          },
          customersAdded: this.customersAdded,
        },
      })
    },
    onAcceptMessageInvitacion() {
      const stepId = this.getStep(this.currentStep).id
      this.$track({
        type: 'system',
        action: 'confirm_invitation',
        category: 'LoyaltyProgramConfig',
        screen: `${stepId.charAt(0).toUpperCase()}${stepId.slice(1)}Step`,
        name: 'Go to next step',
      })
      this.markStepAsComplete(this.currentStep)
      this.currentStep++
    },
    persistLoyaltyConfig() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'LoyaltyProgramConfig',
        screen: 'RegisterSaleStep',
        name: 'Finish configuration',
      })
      rendererEventsService.send(LOYALTY_PROGRAM_EVENTS.channel, {
        event: LOYALTY_PROGRAM_EVENTS.events.initLoyaltyProgram.name,
        data: {
          loyaltyConfigData: {
            customers: this.customersAdded,
            storeNameOld: this.storeName,
            ...this.loyaltyFormInputs,
            prizeDescription: isEmpty(this.loyaltyFormInputs.prizeDescription)
              ? defaultPrizeDescription
              : this.loyaltyFormInputs.prizeDescription,
            rewardAmount: formatNumberToDb(this.loyaltyFormInputs.rewardAmount),
          },
        },
      })
    },
  },
  created() {
    this.loyaltyFormInputs = {
      ...this.loyaltyFormInputs,
      storeName: this.storeName,
    }
    this.$root.$on('loyalty-accept-message-invitation', () => {
      this.onAcceptMessageInvitacion()
    })
  },
  mounted() {
    this.getLayoutHeight()
  },
  beforeDestroy() {
    this.$root.$off('loyalty-accept-message-invitation')
  },
}
</script>

<style lang="scss" scoped>
.stepper {
  box-shadow: none !important;
  height: inherit;
  .stepper__header {
    box-shadow: none !important;
  }
}
</style>
