<template>
  <v-container>
    <FormattedText :value="title" type="text-h4" class="mt-4" />
    <v-row align="center" class="fill-height py-10">
      <v-col cols="12" md="6">
        <div class="d-flex justify-center align-center">
          <div class="d-flex flex-column justify-center align-center">
            <div class="my-4">
              <FormattedText
                intl
                value="loyaltyProgramConfig.stepper.step3.description1"
                type="text-h5"
              />
            </div>
            <div class="my-4">
              <FormattedText
                intl
                value="loyaltyProgramConfig.stepper.step3.description2"
                type="text-h5"
              />
            </div>
            <div class="my-4 w-100">
              <v-img
                class="mx-auto w-100 rounded-lg"
                :src="
                  require('@/assets/gifs/loyaltyProgram/rewardsCustomers.gif')
                "
                style="max-width: 100%;"
              />
            </div>
          </div>
        </div>
      </v-col>
      <v-col cols="12" md="6">
        <div class="d-flex justify-center align-center flex-column">
          <FormattedText
            intl
            value="loyaltyProgramConfig.stepper.step3.description3"
            type="text-h5"
            class="my-4"
          />
          <MobileMockup
            :message="messageWhatsApp"
            :messageTitle="
              getTranslatedText(
                'loyaltyProgramConfig.stepper.step3.messageTitle'
              )
            "
            :messageFooter="
              getTranslatedText(
                'loyaltyProgramConfig.stepper.step3.messageFooter'
              )
            "
          />
        </div>
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
import { mapState } from 'vuex'

import { getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'
import MobileMockup from '@/components/LoyaltyViews/LoyaltyProgramConfigView/LoyaltyConfigStepper/MobileMockup'

export default {
  name: 'RegisterSales',
  components: { FormattedText, MobileMockup },
  props: {
    formPayload: {
      type: Object,
      required: true,
    },
  },
  computed: {
    ...mapState('account', {
      storeName: state => state.data.storeName,
      storePhone: state => state.data.storePhone,
    }),
    title() {
      return `${this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step'
      )} 3: ${this.getTranslatedText('loyaltyProgramConfig.list.step3')}`
    },
    messageWhatsApp() {
      return `${this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step3.message1',
        this.formPayload.rewardAmount
      )}
      \n
      ${this.getTranslatedText('loyaltyProgramConfig.stepper.step3.message2')}
      \n
      ${this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step3.message3',
        this.storeName
      )} ${this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step3.message4',
        this.formPayload.rewardAmount
      )}
      `
    },
  },
  methods: {
    getTranslatedText,
  },
}
</script>

<style lang="scss" scoped>
.w-100 {
  width: 100%;
}
</style>
