<template>
  <v-container
    fluid
    id="loyalty-view-config"
    class="d-flex flex-column justify-center align-center pr-0"
  >
    <section class="w-100 text-center" v-if="!isStarted">
      <div
        class="d-flex flex-wrap align-center justify-space-around fill-height"
      >
        <div class="w-50 px-4 text-justify">
          <div>
            <FormattedText
              intl
              type="text-h2"
              color="textPrimary"
              value="loyaltyProgramConfig.title"
              class="mb-6"
              className="font-weight-bold"
            />
            <FormattedText
              intl
              type="text-h5"
              color="textPrimary"
              value="loyaltyProgramConfig.description"
              class="mb-8"
            />
            <div class="d-flex flex-wrap">
              <v-btn
                x-large
                color="primary"
                class="w-auto mr-4"
                @click="isStarted = true"
                v-track:click="{
                  category: 'LoyaltyProgramConfig',
                  screen: 'Presentation',
                  name: 'Start configuration',
                }"
              >
                <FormattedText
                  intl
                  color="white"
                  value="loyaltyProgramConfig.start"
                />
              </v-btn>
              <v-btn
                x-large
                color="primary"
                text
                :disabled="disableTutorial"
                @click="openVideoDialog"
                v-track:click="{
                  category: 'LoyaltyProgramConfig',
                  screen: 'Presentation',
                  name: 'See video tutorial',
                }"
              >
                <v-icon>mdi-play</v-icon>
                <FormattedText
                  intl
                  color="primary"
                  value="loyaltyProgramConfig.showTutorial"
                />
              </v-btn>
            </div>
          </div>
        </div>
        <div class="w-50 image-container ml-auto">
          <div class="pl-10">
            <v-img
              :src="require('@/assets/loyalty-example.png')"
              class="image-screen"
            />
          </div>
        </div>
      </div>
      <VideoTutorialDialog v-if="tutorialVideoDialog.isOpen" />
    </section>
    <section
      class="loyalty-stepper"
      v-if="isStarted"
      :style="{
        height: `calc(100vh - ${getCommonStyles}px)`,
      }"
    >
      <LoyaltyConfigStepper />
    </section>
  </v-container>
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'

import LOYALTY_PROGRAM_EVENTS from '@/config/events/loyaltyProgram'
import ENROLLED_CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/enrolledCustomersEvents'

import { getAppLayoutHeaderAndFooterHeight } from '@/tools/view'
import { formatNumberFromDb } from '@/tools/numbersFormat'
import { validatePhoneNumber } from '@/tools/customValidations'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import usersActions from '@/store/users/actions.types'
import accountActions from '@/store/account/actions.types'
import loyaltyProgramActions from '@/store/loyaltyProgram/actions.types'
import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import LoyaltyConfigStepper from '@/components/LoyaltyViews/LoyaltyProgramConfigView/LoyaltyConfigStepper'
import VideoTutorialDialog from '@/components/LoyaltyViews/LoyaltyProgramConfigView/VideoTutorialDialog'

export default {
  name: 'LoyaltyProgramConfigView',
  components: {
    FormattedText,
    LoyaltyConfigStepper,
    VideoTutorialDialog,
  },
  data() {
    return {
      layoutCommonElementsHeight: 0,
      isStarted: false,
      steps: [
        { step: 1, text: 'loyaltyProgramConfig.list.step1' },
        { step: 2, text: 'loyaltyProgramConfig.list.step2' },
        { step: 3, text: 'loyaltyProgramConfig.list.step3' },
      ],
    }
  },
  computed: {
    ...mapState('app', ['pendingSyncOps']),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('account', {
      accountData: state => state.data,
    }),
    ...mapState('loyaltyProgram', {
      loyaltyProgramData: state => state.data,
    }),
    ...mapState('loyaltyProgramView', ['tutorialVideoDialog']),
    ...mapGetters('account', ['getCountry']),
    getCommonStyles() {
      return this.layoutCommonElementsHeight
    },
    disableTutorial() {
      return !navigator.onLine
    },
  },
  methods: {
    ...mapActions('users', [usersActions.updateUserPermissions]),
    ...mapActions('account', [
      accountActions.setOwnerAndStoreNames,
      accountActions.setLoyaltyData,
    ]),
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setTutorialVideoDialogStatus,
    ]),
    ...mapActions('loyaltyProgram', [
      loyaltyProgramActions.setEnrolledCustomers,
      loyaltyProgramActions.setLoyaltyFetching,
    ]),
    getLayoutHeight() {
      this.layoutCommonElementsHeight = getAppLayoutHeaderAndFooterHeight(
        'loyalty-view-config'
      )
    },
    changeStoreName(newStoreName) {
      if (newStoreName === this.accountData.storeName) return
      this[accountActions.setOwnerAndStoreNames]({
        ...this.accountData,
        storeName: newStoreName,
      })
    },
    setLoyaltyConfig({
      enrolledCustomers,
      customers,
      sales,
      rewardAmount,
      prizeDescription,
    }) {
      this[loyaltyProgramActions.setLoyaltyFetching](true)
      this[loyaltyProgramActions.setEnrolledCustomers]({
        enrolledCustomers,
        customers,
        sales,
      })
      this[accountActions.setLoyaltyData]({
        loyaltyProgramActived: 1,
        rewardAmount,
        prizeDescription,
      })
    },
    sendInvitations() {
      const enrolledCustomersForSend = this.loyaltyProgramData.enrolledCustomers.reduce(
        (enrolledCustomersToSendMessage, enrolledCustomer) => {
          if (validatePhoneNumber(enrolledCustomer.customer.phone)) {
            enrolledCustomersToSendMessage.push({
              ...enrolledCustomer,
              amount: formatNumberFromDb(enrolledCustomer.amount),
            })
          }
          return enrolledCustomersToSendMessage
        },
        []
      )
      this[loyaltyProgramActions.setLoyaltyFetching](true)
      rendererEventsService.send(ENROLLED_CUSTOMERS_DB_API_EVENTS.channel, {
        event: ENROLLED_CUSTOMERS_DB_API_EVENTS.events.sendInvitations.name,
        data: {
          enrolledCustomers: enrolledCustomersForSend,
          securityData: this.accountData.security,
          storeName: this.accountData.storeName,
          phoneCode: this.getCountry.phoneCode,
          pos: this.accountData.pos,
        },
      })
    },
    openVideoDialog() {
      this[loyaltyProgramViewActions.setTutorialVideoDialogStatus](true)
    },
    async loyaltyListener(event, payload) {
      const loyaltyEvents = LOYALTY_PROGRAM_EVENTS.events
      const replies = {
        [loyaltyEvents.initLoyaltyProgram.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'loyalty_configuration',
            category: 'LoyaltyProgramConfig',
            screen: 'RegisterSaleStep',
            name: 'Go to loyalty program',
          })
          const {
            enrolledCustomers,
            customers,
            sales,
            rewardAmount,
            storeName,
            prizeDescription,
          } = payload.data
          this.changeStoreName(storeName)
          this.setLoyaltyConfig({
            enrolledCustomers,
            customers,
            sales,
            rewardAmount,
            prizeDescription,
          })
          this.$root.$emit('sendOpsToSync')
          setTimeout(() => {
            this.sendInvitations()
            this.$router.push({ name: 'LoyaltyProgram' })
          }, 450)
        },
        [loyaltyEvents.initLoyaltyProgram.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'LoyaltyProgramConfig',
            screen: 'RegisterSaleStep',
            name: 'Error configuring loyalty program',
          })
          notificationsService.showError(
            'notification.loyaltyProgram.initError',
            this.$vuetify.lang
          )
          this.$router.push({ name: 'Customers' })
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    async enrolledCustomersListener(event, payload) {
      const events = ENROLLED_CUSTOMERS_DB_API_EVENTS.events
      const replies = {
        [events.sendInvitations.replies.error]: () => {
          this[loyaltyProgramActions.setLoyaltyFetching](false)
          notificationsService.showError(
            'notification.loyaltyProgram.sendInvitationsError',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      LOYALTY_PROGRAM_EVENTS.replyChannel,
      this.loyaltyListener
    )
    rendererEventsService.subscribe(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomersListener
    )
  },
  mounted() {
    this.getLayoutHeight()
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      LOYALTY_PROGRAM_EVENTS.replyChannel,
      this.loyaltyListener
    )
    rendererEventsService.removeListener(
      ENROLLED_CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.enrolledCustomersListener
    )
  },
}
</script>

<style lang="scss" scoped>
#loyalty-view-config {
  height: 100%;
  margin: 0 auto;
  .loyalty-logo {
    height: 10em;
  }
  .loyalty-stepper {
    height: 100%;
    width: 100%;
  }
  ol {
    font-size: 2.125rem;
    color: var(--v-textPrimary-base);
  }
  .w-100 {
    width: 100%;
  }
  .btn-position {
    position: absolute;
    bottom: 2rem;
    right: 2rem;
  }
}
.w-50 {
  width: 50%;
}
.w-auto {
  width: auto;
}
.image-container {
  max-width: max-content;
  margin-left: auto;
  margin-right: auto;
  right: 0;
}
.image-screen {
  border-left: 10px solid var(--v-primary-base);
  border-top: 10px solid var(--v-primary-base);
  border-bottom: 10px solid var(--v-primary-base);
  border-top-left-radius: 16px;
  border-bottom-left-radius: 16px;
  max-height: 700px;
}
</style>
