<template>
  <VideoPlayerDialog :config="videoConfig.dialogData" />
</template>

<script>
import { mapActions, mapState } from 'vuex'

import loyaltyProgramViewActions from '@/store/loyaltyProgramView/actions.types'

import VideoPlayerDialog from '@/components/shared/VideoPlayerDialog'
import setConfig from '@/components/LoyaltyViews/LoyaltyProgramConfigView/VideoTutorialDialog/videoDialogConfig'

export default {
  name: 'VideoTutorialDialog',
  components: {
    VideoPlayerDialog,
  },
  computed: {
    ...mapState('loyaltyProgramView', ['tutorialVideoDialog']),
    videoConfig() {
      return setConfig(
        {
          isOpen: this.tutorialVideoDialog.isOpen,
          videoUrl: 'https://www.youtube-nocookie.com/embed/iM1YG6wndXk',
        },
        {
          closeDialog: this.closeDialog,
        }
      )
    },
  },
  methods: {
    ...mapActions('loyaltyProgramView', [
      loyaltyProgramViewActions.setTutorialVideoDialogStatus,
    ]),
    closeDialog() {
      this[loyaltyProgramViewActions.setTutorialVideoDialogStatus](false)
    },
  },
}
</script>
