<template>
  <v-container>
    <FormattedText :value="title" type="text-h4" class="mt-4" />
    <v-row no-gutters align="center" justify="center" class="fill-height py-10">
      <v-col cols="12">
        <v-row align="center">
          <v-col cols="10">
            <FormattedText
              intl
              value="loyaltyProgramConfig.stepper.step1.labelStoreName"
              type="text-subtitle-1"
              className="font-weight-bold"
            />
          </v-col>
          <v-col cols="3" class="field-col-height">
            <v-text-field
              id="storeName-input"
              ref="storeName"
              class="custom-text-field-large"
              filled
              rounded
              color="primary"
              :label="
                getTranslatedText(
                  'loyaltyProgramConfig.stepper.step1.placeholderStoreName'
                )
              "
              v-model="inputs.storeName"
              :error-messages="onValidateFields('storeName')"
              @focus="currentFocus = 'storeName'"
              @blur="$v.inputs.storeName.$touch()"
            />
          </v-col>
          <v-col cols="7" class="pl-4 field-col-height">
            <FormattedText
              intl
              value="loyaltyProgramConfig.stepper.step1.descriptionStoreName"
              class="pt-4"
            />
          </v-col>
        </v-row>
      </v-col>
      <v-col cols="12">
        <v-row align="center">
          <v-col cols="10">
            <FormattedText
              intl
              value="loyaltyProgramConfig.stepper.step1.labelQuantity"
              type="text-subtitle-1"
              className="font-weight-bold"
            />
          </v-col>
          <v-col cols="3" class="field-col-height">
            <MoneyTextField
              ref="rewardAmount"
              :options="getMoneyInputsConfig"
              v-model.number="inputs.rewardAmount"
              :config="{
                fieldName: 'rewardAmount',
                label: getTranslatedText(
                  'loyaltyProgramConfig.stepper.step1.placeholderQuantity'
                ),
                color: 'primary',
                filled: true,
                rounded: true,
                class: 'custom-text-field-large',
                errorMessage: onValidateFields,
              }"
              @focus="currentFocus = 'rewardAmount'"
              @blur="$v.inputs.rewardAmount.$touch()"
            />
          </v-col>
          <v-col cols="7" class="pl-4 field-col-height">
            <FormattedText
              intl
              value="loyaltyProgramConfig.stepper.step1.descriptionQuantity"
              class="pt-4"
            />
          </v-col>
        </v-row>
      </v-col>
      <v-col cols="12">
        <v-row align="center">
          <v-col cols="10">
            <FormattedText
              intl
              value="loyaltyProgramConfig.stepper.step1.labelPrice"
              type="text-subtitle-1"
              className="font-weight-bold"
            />
          </v-col>
          <v-col cols="7" class="field-col-height">
            <v-text-field
              id="prizeDescription-input"
              ref="prizeDescription"
              class="custom-text-field-large"
              filled
              rounded
              maxlength="200"
              counter
              color="primary"
              :label="
                getTranslatedText(
                  'loyaltyProgramConfig.stepper.step1.placeholderPrice'
                )
              "
              v-model="inputs.prizeDescription"
              :error-messages="onValidateFields('prizeDescription')"
              @focus="currentFocus = 'prizeDescription'"
              @blur="$v.inputs.prizeDescription.$touch()"
            />
          </v-col>
          <v-col cols="3" />
        </v-row>
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
import { required } from 'vuelidate/lib/validators'

import { getTranslatedText } from '@/tools/data'
import {
  getDecimalsCount,
  moneyTextFieldCountryConfig,
} from '@/tools/numbersFormat'
import { validate } from '@/tools/validations'

import FormattedText from '@/components/shared/FormattedText'
import MoneyTextField from '@/components/shared/MoneyTextField'

export default {
  name: 'ConfigProgram',
  components: {
    FormattedText,
    MoneyTextField,
  },
  props: {
    formPayload: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      inputs: {
        storeName: '',
        prizeDescription: '',
        rewardAmount: 0,
      },
      currentFocus: '',
    }
  },
  computed: {
    title() {
      return `${this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step'
      )} 1: ${this.getTranslatedText('loyaltyProgramConfig.list.step1')}`
    },
    getMoneyInputsConfig() {
      const { currency, locale, prefix } = moneyTextFieldCountryConfig()
      return { currency, locale, prefix, precision: 0 } || { precision: 2 }
    },
  },
  validations() {
    return this.setFormValidators()
  },
  methods: {
    getTranslatedText,
    setFormValidators() {
      const validations = {
        inputs: {
          storeName: { required },
          prizeDescription: {},
          rewardAmount: {
            required,
            minValue: value => value > 0,
            maxValue: value => value < 1000000,
            maxDecimals: value => getDecimalsCount(value) <= 4,
          },
        },
      }
      return validations
    },
    onValidateFields(input) {
      return validate(this.$v.inputs, input, { fn: this.getTranslatedText })
    },
    emitValues() {
      this.$emit('loyalty-form-values', {
        inputs: this.inputs,
        isValid: !this.$v.$invalid,
      })
    },
  },
  mounted() {
    this.inputs.storeName = this.formPayload.storeName
    this.inputs.rewardAmount = this.formPayload.rewardAmount
    this.inputs.prizeDescription = this.formPayload.prizeDescription
  },
  updated() {
    this.emitValues()
  },
}
</script>

<style lang="scss" scoped>
.field-col-height {
  height: 110px;
}
</style>
