<template>
  <v-container>
    <FormattedText :value="title" type="text-h4" class="my-4" />
    <FormattedText
      intl
      value="loyaltyProgramConfig.stepper.step2.description"
      class="my-4"
      class-name="font-weight-bold"
    />
    <v-container fluid class="customer-container">
      <PaginatedTableSelection
        :config="tableConfig"
        :key="componentKey"
        @updateSelectedItems="updateSelectedCustomers"
      >
        <template v-slot:top>
          <div class="d-flex justify-space-between mb-4">
            <CustomButton
              intl
              text="loyaltyProgramConfig.stepper.step2.newClient"
              icon="mdi-account-plus-outline"
              textClass="pl-2"
              large
              @click="addCustomer"
              v-track:click="{
                category: 'LoyaltyProgramConfig',
                screen: 'InviteCustomersStep',
                name: 'Create customer',
              }"
            />
            <v-text-field
              v-model="search"
              filled
              rounded
              clearable
              hide-details
              :label="getTranslatedText('shared.search')"
              class="input-search"
              @input="searchCustomer"
            />
          </div>
        </template>
        <template v-slot:phone="{ item }">
          <span v-if="showPhoneNumber(item.phone)">
            {{ item.phone }}
          </span>
          <InputPhone v-else :customer="item" />
        </template>
      </PaginatedTableSelection>
    </v-container>
  </v-container>
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'

import CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/customersEvents'
import SYNCHRONIZATION_EVENTS from '@/config/events/synchronization'

import { getTranslatedText } from '@/tools/data'
import { validatePhoneNumber } from '@/tools/customValidations'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import customersViewActions from '@/store/customersView/actions.types'
import customersActions from '@/store/customers/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import PaginatedTableSelection from '@/components/shared/PaginatedTableSelection'
import CustomButton from '@/components/shared/CustomButton'
import setTableConfig from '@/components/LoyaltyViews/LoyaltyProgramConfigView/LoyaltyConfigStepper/steps/InviteCustomers/tableConfig'
import InputPhone from '@/components/LoyaltyViews/InputPhone'

export default {
  name: 'InviteCustomers',
  components: {
    InputPhone,
    FormattedText,
    PaginatedTableSelection,
    CustomButton,
  },
  props: {
    step: {
      type: Number,
      required: true,
    },
    selectedCustomers: {
      type: Array,
      required: true,
    },
  },
  data() {
    return {
      search: '',
      componentKey: 0,
    }
  },
  computed: {
    ...mapState('app', ['windowSize']),
    ...mapGetters('customers', ['getFilteredData']),
    title() {
      return `${this.getTranslatedText(
        'loyaltyProgramConfig.stepper.step'
      )} 2: ${this.getTranslatedText('loyaltyProgramConfig.list.step2')}`
    },
    tableConfig() {
      return setTableConfig(
        {
          items: this.getFilteredData,
          selectedItems: this.selectedCustomers,
          windowHeight: this.windowSize.y,
        },
        {
          context: this,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('customersView', [
      customersViewActions.setSearchTermFilter,
      customersViewActions.setAddCustomerDialogStatus,
    ]),
    ...mapActions('customers', [customersActions.editCustomerField]),
    addCustomer() {
      this[customersViewActions.setAddCustomerDialogStatus](true)
    },
    searchCustomer(searchTerm) {
      this[customersViewActions.setSearchTermFilter](searchTerm)
    },
    updateSelectedCustomers(selectedItems) {
      this.$emit('updateSelectedCustomers', selectedItems)
    },
    showPhoneNumber(phone) {
      return validatePhoneNumber(phone)
    },
    customerWasEditedListener(event, payload) {
      const replies = {
        [CUSTOMERS_DB_API_EVENTS.events.updateById.replies.success]: () => {
          rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
            event: SYNCHRONIZATION_EVENTS.events.createOperation.name,
            data: {
              entityData: JSON.parse(JSON.stringify(payload.data)),
              entityName: 'customers',
            },
          })
          this[customersActions.editCustomerField]({
            id: payload.data._id,
            phone: payload.data.mobile_number,
          })
        },
        [CUSTOMERS_DB_API_EVENTS.events.updateById.replies.error]: () => {
          notificationsService.showError(
            'loyaltyProgramConfig.stepper.step2.errorSavePhone',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  watch: {
    step: function(val) {
      // This is for force rerender table
      if (val === 2) this.componentKey += 1
    },
  },
  mounted() {
    rendererEventsService.subscribe(
      CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.customerWasEditedListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CUSTOMERS_DB_API_EVENTS.replyChannel,
      this.customerWasEditedListener
    )
    this[customersViewActions.setSearchTermFilter](null)
  },
}
</script>

<style lang="scss" scoped>
.customer-container {
  height: 36rem;
}

.input-search {
  max-width: 214px;
  border-radius: 12px;
}
</style>
